CREATE TABLE "InventoryCategory" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InventoryCategory_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "InventoryCategory_name_key" ON "InventoryCategory"("name");
CREATE UNIQUE INDEX "InventoryCategory_code_key" ON "InventoryCategory"("code");
CREATE TABLE "Supplier" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"contactPerson" TEXT,"phone" TEXT,"email" TEXT,"address" TEXT,"taxNumber" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Supplier_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Supplier_code_key" ON "Supplier"("code"); CREATE UNIQUE INDEX "Supplier_taxNumber_key" ON "Supplier"("taxNumber");
CREATE TABLE "InventoryItem" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"categoryId" TEXT NOT NULL,"supplierId" TEXT,"unit" TEXT NOT NULL,"store" TEXT NOT NULL,"quantity" INTEGER NOT NULL DEFAULT 0,"reorderLevel" INTEGER NOT NULL DEFAULT 0,"expiresAt" TIMESTAMP(3),"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deletedAt" TIMESTAMP(3),CONSTRAINT "InventoryItem_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "InventoryItem_code_key" ON "InventoryItem"("code"); CREATE INDEX "InventoryItem_name_idx" ON "InventoryItem"("name"); CREATE INDEX "InventoryItem_categoryId_isActive_idx" ON "InventoryItem"("categoryId","isActive"); CREATE INDEX "InventoryItem_supplierId_idx" ON "InventoryItem"("supplierId");
CREATE TABLE "InventoryMovement" ("id" TEXT NOT NULL,"itemId" TEXT NOT NULL,"type" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"balance" INTEGER NOT NULL,"reference" TEXT,"notes" TEXT,"actorId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InventoryMovement_pkey" PRIMARY KEY ("id")); CREATE INDEX "InventoryMovement_itemId_createdAt_idx" ON "InventoryMovement"("itemId","createdAt");
CREATE TABLE "Ambulance" ("id" TEXT NOT NULL,"number" TEXT NOT NULL,"registration" TEXT NOT NULL,"vehicleType" TEXT NOT NULL,"driver" TEXT,"driverContact" TEXT,"status" TEXT NOT NULL DEFAULT 'Available',"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Ambulance_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Ambulance_number_key" ON "Ambulance"("number"); CREATE UNIQUE INDEX "Ambulance_registration_key" ON "Ambulance"("registration"); CREATE INDEX "Ambulance_status_isActive_idx" ON "Ambulance"("status","isActive");
CREATE TABLE "AmbulanceBooking" ("id" TEXT NOT NULL,"number" TEXT NOT NULL,"patientId" TEXT NOT NULL,"ambulanceId" TEXT,"pickup" TEXT NOT NULL,"destination" TEXT NOT NULL,"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"tripStartedAt" TIMESTAMP(3),"tripEndedAt" TIMESTAMP(3),"charges" DECIMAL(12,2) NOT NULL DEFAULT 0,"status" TEXT NOT NULL DEFAULT 'Requested',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AmbulanceBooking_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "AmbulanceBooking_number_key" ON "AmbulanceBooking"("number"); CREATE INDEX "AmbulanceBooking_patientId_requestedAt_idx" ON "AmbulanceBooking"("patientId","requestedAt"); CREATE INDEX "AmbulanceBooking_ambulanceId_status_idx" ON "AmbulanceBooking"("ambulanceId","status");
CREATE TABLE "InsuranceProvider" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"contact" TEXT,"address" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InsuranceProvider_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "InsuranceProvider_code_key" ON "InsuranceProvider"("code");
CREATE TABLE "PatientInsurance" ("id" TEXT NOT NULL,"patientId" TEXT NOT NULL,"providerId" TEXT NOT NULL,"policyNumber" TEXT NOT NULL,"memberNumber" TEXT,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"coverageLimit" DECIMAL(12,2) NOT NULL,"relationship" TEXT NOT NULL,"priority" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PatientInsurance_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "PatientInsurance_policyNumber_key" ON "PatientInsurance"("policyNumber"); CREATE INDEX "PatientInsurance_patientId_isActive_idx" ON "PatientInsurance"("patientId","isActive"); CREATE INDEX "PatientInsurance_providerId_idx" ON "PatientInsurance"("providerId");
CREATE TABLE "InsuranceClaim" ("id" TEXT NOT NULL,"number" TEXT NOT NULL,"patientId" TEXT NOT NULL,"insuranceId" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"claimedAmount" DECIMAL(12,2) NOT NULL,"approvedAmount" DECIMAL(12,2) NOT NULL DEFAULT 0,"rejectedAmount" DECIMAL(12,2) NOT NULL DEFAULT 0,"patientResponsibility" DECIMAL(12,2) NOT NULL DEFAULT 0,"status" TEXT NOT NULL DEFAULT 'Draft',"submittedAt" TIMESTAMP(3),"settledAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InsuranceClaim_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "InsuranceClaim_number_key" ON "InsuranceClaim"("number"); CREATE INDEX "InsuranceClaim_patientId_status_idx" ON "InsuranceClaim"("patientId","status"); CREATE INDEX "InsuranceClaim_insuranceId_idx" ON "InsuranceClaim"("insuranceId"); CREATE INDEX "InsuranceClaim_invoiceId_idx" ON "InsuranceClaim"("invoiceId");
CREATE TABLE "LabOrder" ("id" TEXT NOT NULL,"number" TEXT NOT NULL,"patientId" TEXT NOT NULL,"doctor" TEXT NOT NULL,"tests" TEXT[],"priority" TEXT NOT NULL,"clinicalNotes" TEXT,"sampleType" TEXT NOT NULL,"collectedAt" TIMESTAMP(3),"collectedBy" TEXT,"status" TEXT NOT NULL DEFAULT 'Ordered',"version" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "LabOrder_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "LabOrder_number_key" ON "LabOrder"("number"); CREATE INDEX "LabOrder_patientId_createdAt_idx" ON "LabOrder"("patientId","createdAt"); CREATE INDEX "LabOrder_status_createdAt_idx" ON "LabOrder"("status","createdAt");
CREATE TABLE "LabResult" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"test" TEXT NOT NULL,"value" TEXT NOT NULL,"unit" TEXT,"referenceRange" TEXT,"abnormal" BOOLEAN NOT NULL DEFAULT false,"notes" TEXT,"enteredBy" TEXT NOT NULL,"enteredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"verifiedBy" TEXT,"verifiedAt" TIMESTAMP(3),CONSTRAINT "LabResult_pkey" PRIMARY KEY ("id")); CREATE INDEX "LabResult_orderId_idx" ON "LabResult"("orderId");
CREATE TABLE "RadiologyOrder" ("id" TEXT NOT NULL,"number" TEXT NOT NULL,"patientId" TEXT NOT NULL,"investigation" TEXT NOT NULL,"doctor" TEXT NOT NULL,"scheduledAt" TIMESTAMP(3),"findings" TEXT,"impression" TEXT,"reportedBy" TEXT,"verifiedBy" TEXT,"attachmentRef" TEXT,"status" TEXT NOT NULL DEFAULT 'Ordered',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RadiologyOrder_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "RadiologyOrder_number_key" ON "RadiologyOrder"("number"); CREATE INDEX "RadiologyOrder_patientId_createdAt_idx" ON "RadiologyOrder"("patientId","createdAt"); CREATE INDEX "RadiologyOrder_status_createdAt_idx" ON "RadiologyOrder"("status","createdAt");
ALTER TABLE "InventoryItem" ADD CONSTRAINT "InventoryItem_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "InventoryCategory"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InventoryItem" ADD CONSTRAINT "InventoryItem_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "InventoryMovement" ADD CONSTRAINT "InventoryMovement_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "InventoryItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "AmbulanceBooking" ADD CONSTRAINT "AmbulanceBooking_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "Patient"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "AmbulanceBooking" ADD CONSTRAINT "AmbulanceBooking_ambulanceId_fkey" FOREIGN KEY ("ambulanceId") REFERENCES "Ambulance"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "PatientInsurance" ADD CONSTRAINT "PatientInsurance_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "Patient"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "PatientInsurance" ADD CONSTRAINT "PatientInsurance_providerId_fkey" FOREIGN KEY ("providerId") REFERENCES "InsuranceProvider"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "InsuranceClaim" ADD CONSTRAINT "InsuranceClaim_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "Patient"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InsuranceClaim" ADD CONSTRAINT "InsuranceClaim_insuranceId_fkey" FOREIGN KEY ("insuranceId") REFERENCES "PatientInsurance"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InsuranceClaim" ADD CONSTRAINT "InsuranceClaim_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "Invoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "LabOrder" ADD CONSTRAINT "LabOrder_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "Patient"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "LabResult" ADD CONSTRAINT "LabResult_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "LabOrder"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RadiologyOrder" ADD CONSTRAINT "RadiologyOrder_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "Patient"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
